INSERT INTO CadModel VALUES(148,'f32e829667507ab18924120dfad0e290','44d585f5-6359-4a74-8220-761d8f26f690','Turbo-Lada Samara GTR-2 /  --','What do you do when you need more power but cant afford developing a new engine? And a bigger engine wouln''t fit in the car anyways? Simple, you add another one just like it in the back of the car, and you have double the power! The engines are slightly detuned for reliability reasons, running at 631 hp each, but they can be tuned up to 884 hp for qualifying. With an added weight of just 163 kg over the single engine car, the power to weight ratio is up around 80%. Besides, the weight distribution is now a dead solid 50:50. The radiators and coolers in the back were moved out to the sides. The rear engine uses a dual intercooler setup. The rear end of the bodywork is now entirely made of carbon fiber and can be detatched from the rest of the car along with the front, leaving just the passenger cabin (completely unchanged from the single engine car) left of the monocoque chassis. The fuel tank is relocated to the (former) drive shaft tunnel. The two gearboxes are not interconnected mechanically, but are electronically synchronised, as are the engines themselves. One single engine can run alone, however this leaves the car with two wheel drive. To save weight, only the rear gearbox actually has a reverse gear, the front gearbox will be in neutral and the computer disables the throttle for that engine. Max power (qualifying tune): 1768 hp @ 8700 RPM, redline 9500 RPM, est. weight 1285 kg #2108',NULL,'lada',NULL,'samara',4.500740051269530361,2.092679977416989967,1.228842912556959988,'red',NULL,'passenger','https://3dwarehouse.sketchup.com/model/f32e829667507ab18924120dfad0e290/TurboLada-Samara-GTR2',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(149,'7d4c3d9795570647657231d17e42d06f','44d585f5-6359-4a74-8220-761d8f26f690','VAZ 2101 Zhiguli (rally/racing version)','originally made by bogdach(the vaz dealership in 3d Wharehouse LOL). Rwd 4 turbo intercooled dohc engine, all cleaned up (bumpers), old skyline racing styled intercooler, it looks a lot like my version of the marian bmw 2002. A treat to VAZ or russian car lovers!!!!! #2101 #biturbo #buggy #car #carburator #door #dune #engine #ferrari #ford #GSX #holley #mitsubishi #muscle #nissan #off #ralli #road #rs #sport #subaru #TDC #tuned #turbo #two #v12 #v6 #v8 #vaz','triangles','lada',NULL,'2101',3.823732137680050159,1.69228076934814009,1.356965605169530021,NULL,NULL,'passenger',NULL,NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(150,'3e241d687f0b630839cc19d48e3f4f5','44d585f5-6359-4a74-8220-761d8f26f690','Turbo-Lada Samara Pikes Peak Special','Pikes Peak Hill Climb special version of the Turbo-Lada Samara. Featuring huge wings front and rear, to help plant the 1504 hp to the loose gravel hills of Pikes Peak. An extreme evolution of the original Turbo-Lada Samara. For each engine: Bore: 101 mm, Stroke: 74 mm (bore/stroke ratio: 1.36), Total capacity 2370 cc, 752 hp @ 9500 rpm, 668 nm @ 7600 rpm #2108 #auto #autox #autocross #axle #bimotor #bogdach #camion #Car #car_car #car_car_car #car_car_car_car #car_suspension #car_tire #car_wheels #car_window #car_with_wheels #carmirrors #cars #cart #challenge #championship #charged #Climb #competition #course #detail #drive #driveshaft #drivetrain #dualengine #dw26 #dw26_car #equal #Escudo #exaggerated #extreme #fia #frame #gcars #header #headers #Hill #homologation #ice #intercooler #International #lada #lada_car #ladasamara #ladaturbo',NULL,'lada',NULL,'samara',4.825773239135740411,1.904881477355959917,1.260266147146470006,'red',NULL,'passenger','https://3dwarehouse.sketchup.com/model/3e241d687f0b630839cc19d48e3f4f5/TurboLada-Samara-Pikes-Peak-Special',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(151,'4b94cdc9c703d00fef3ecc8551d2c1fa','44d585f5-6359-4a74-8220-761d8f26f690','1995 Turbo-Lada Samara R2500','A factory made homologation road car of the rally car, as 2500 of this had to be made to homologate the car for rally in group A. Has some added detail: Improved frontal frame, more removable body parts, New wheel design, New headlamp design with dedicated high beam reflectors fitted with HID technology 75w bulbs (equal to 120w halogen bulbs), eliminating the need for wind-grabbing externally mounted driving lamps, new front indicator placement (in the front bumper), improved front bumper with ducts leading air to the side mounted radiator and the dry sump oil cooler, smoothed entire body, new taillights design with middle reflex plate section. New vinyl emblems around the car. New mirrors. The car is lowered a bit more (now 80mm lower than a standard Samara). It has working headlamps and taillamps, and reflection settings (paint: 35, glass:50, reflectors:100) (SU Podium). The 2.0L is de-restricted, and tuned to 325hp. But the engine can be tuned to over 600hp. Weight: 1295kg. Fuel consumption (100km/h cruise): 14L/100km #2108 #bogdach',NULL,'lada','1995','samara',4.210019826889039863,1.809497952461240012,1.379559993743900038,'gray',NULL,'passenger','https://3dwarehouse.sketchup.com/model/4b94cdc9c703d00fef3ecc8551d2c1fa/1995-TurboLada-Samara-R2500',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(152,'214f26c4fc425627ef3ecc8551d2c1fa','44d585f5-6359-4a74-8220-761d8f26f690','1995 Turbo-Lada Samara Rally car Gr. A','This is a group A rally car developed from the 650-spec race car, mounted with ice racing tires. New features are the wheels, mudflaps, and a new front bumper, with Lightforce 240 HID lamps. Group-A specification: Engine displacement: 1999cc, 34mm intake restrictor, 300bhp, 580Nm. Weight: 1230 kg. This is probably the most realistic approach towards a rally car I have ever made, maybe except for the exhaust system (or lack thereof) and the usual exaggerated dimensions. I am real happy with it in every aspect! My favorite creation. Competes in rallies with Subaru Impreza, Mitsubishi Lancer, Toyota Celica GT4, Ford Escort RS Cosworth, etc. #2108 #2113 #autox #autocross #bogdach #Car #challenge #championship #charged #competition #compomotive #corse #course #dw26 #fia #gcars #groupa #homologation #ice #intercooler #international #lada #lightforce #mud #RAC #racing #raid #rally #rallye #rollcage #russian #samara #snow #soviet #sparco #special #sputnik #togliatti #track #tuning #turbo #uaz #vaz #volga #WRC # #',NULL,'lada','1995','samara',4.131979942321780009,1.855605959892270063,1.398820042610170012,NULL,NULL,'passenger','https://3dwarehouse.sketchup.com/model/214f26c4fc425627ef3ecc8551d2c1fa/1995-TurboLada-Samara-Rally-car-Gr-A',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(153,'e39215e03ab8e65e68428aabd2c41ee8','44d585f5-6359-4a74-8220-761d8f26f690','Another racing VAZ but different model ->2106 Ti-R','Original by ZXT, I painted it, softned A LOT of it (mostly the chassis) Installed a fat turbo and a big intercooler and air filter. I''ve modified the rollcage of my other vaz to fit in this one, also took the seats from there. Take a look at it, its really nice. oh and look under the hood to see the modifications. and try to find my most wanted model 1993 toyota starlet gt turbo or normal!!PLZZZZ #2101 #2106 #biturbo #buggy #car #carburator #door #dune #engine #ferrari #ford #GSX #gt #holley #mitsubishi #muscle #nissan #off #ralli #rally_sport #road #rs #sport #starlet #subaru #TDC #toyota #tuned #turbo #two #v12 #v6 #v8 #vaz',NULL,'lada',NULL,'2106',4.267643928527830254,1.831460595130919966,1.509357830102090014,'yellow',NULL,'passenger',NULL,NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(154,'107a17c6f2dd9c488924120dfad0e290','44d585f5-6359-4a74-8220-761d8f26f690','Turbo-Lada Samara GTR-2 Race Car (Narva-Pneumant livery)','Car cars car : Turbo-Lada Racing car with sponsors. #2108 #bimoto #bimotor #bogdach #Car #car_car #car_car_car #car_car_car_car #car_suspension #car_tire #car_wheels #car_window #car_with_wheels #carmirrors #cars #cart #Championship #charged #dualengine #dw26 #dw26_car #equal #FIA #frame #gcars #GT #GT1 #GT2 #GTC #GTO #GTR #GTU #header #headers #imsa #intercooler #lada #lada_car #ladasamara #ladaturbo #ladda #lenght #manifold #podium #race #racing #rally #rallye #red #red_car #rollcage #russian #samara #soviet #space #supodium #tire #togliatti #turbo #turbolada #turbolader #twinengine #uaz #vaz #volga #wheel # # # # # # # # # #',NULL,'lada',NULL,'samara',4.500740051269530361,2.092679977416989967,1.228842912556959988,'red',NULL,'passenger','https://3dwarehouse.sketchup.com/model/107a17c6f2dd9c488924120dfad0e290/TurboLada-Samara-GTR2-Race-Car-NarvaPneumant-livery',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(155,'11d3fce540394c96f6ec7cc92e9fdd13','44d585f5-6359-4a74-8220-761d8f26f690','vaz 2106','vaz author unknown #vaz','triangles','lada',NULL,'2106',3.939240694046020064,1.665780663490300074,1.372816684550340006,'blue',NULL,'passenger','https://3dwarehouse.sketchup.com/model/11d3fce540394c96f6ec7cc92e9fdd13/vaz-2106',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(156,'f2422eb6b55e8fb0ef3ecc8551d2c1fa','44d585f5-6359-4a74-8220-761d8f26f690','Turbo-Lada Samara R-650 4WD','A 4WD version of the Turbo-Lada Samara, with a highly tuned engine, bored to 2.4 L, fitted with custom built headers (equal length), mating a HUGE turbo (moved away from the engine because of too little space), sucking air from the front bumper mounted (big) air filter, and feeding it into a front mounted (bigger!) intercooler, and into the engine. The exhaust consists of a 5.5 inch pipe, splitting into two 3.5ers spewing out flames behind the front wheel, along with the 3 pipe from the wastegate (NO cats or mufflers!). Also new is a reinforced roll cage, and a complete frontal frame supporting the suspension and engine, as the front unibody construction is gone. Bodywork consists of new front fenders, a modified front bumper from the R (FWD) version, with cutouts to feed the coolers with air. Different hood, helping the hot air escape from the engine compartment. An enlarged rear spoiler, and a diffuser secures lots of downforce. Inside the car is a basic interior with gauges for speed, revs and turbo pressure. A shift light lights up at 7500 rpm. The engine produces 650hp @ 6500 rpm. Rev limiter at 7900 rpm. Weight: 1280 kg Fuel consumption (100km/h cruise): 22L/100km #2108',NULL,'lada',NULL,'samara',4.098269939422610086,1.855605959892270063,1.351430058479309971,'red',NULL,'passenger','https://3dwarehouse.sketchup.com/model/f2422eb6b55e8fb0ef3ecc8551d2c1fa/TurboLada-Samara-R650-4WD',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(157,'a3b3996b7a6fe9892156f48e4f10ccf0','44d585f5-6359-4a74-8220-761d8f26f690','LADA V12','my own version of the LADA 2106 originally by ZXT. Fitted V12 engine (by FVDESIGNS) in boot of car... generally speaking i think the overall thing looks pretty damn good. you may upload any changes to the model please note that it is ZXT and FVDESIGNS models originally, i just put the two together. thanks. #LADA_VAZ_2106_2103_V12','other','lada',NULL,'2106',5.432005882263180042,4.936747968196869785,1.518190279544799904,'black',NULL,'passenger','https://3dwarehouse.sketchup.com/model/a3b3996b7a6fe9892156f48e4f10ccf0/LADA-V12',NULL,NULL,'{"VehicleType":null}');
