INSERT INTO CadModel VALUES(162,'862a345b6328d641ef3ecc8551d2c1fa','44d585f5-6359-4a74-8220-761d8f26f690','Team LukOil Racing TurboLada Samara Ice racer.','This is an Ice racing car based on the R2500, fitted with an engine from the 650-4WD (2.4L), modified to produce only 533 hp, but is much more responsive, a much broader powerband, and has almost no turbo lag. Lightened to 1172 kg. #2108 #bogdach #Car #cars #charged #circuit #class #derby #dw26 #dyno #frozen #gcars #ice #intercooler #lada #lag #lake #LukOil #Oil #racing #rally #rally_school #rallye #rollcage #russian #samara #snow #soviet #street #team #togliatti #track_day #trail #trainer #training #tuning #turbo #uaz #vaz #vehicle #volga # # # # # # # # # #',NULL,'lada',NULL,'samara',4.236279964447019708,1.809497952461240012,1.405220031738279918,NULL,NULL,'passenger','https://3dwarehouse.sketchup.com/model/862a345b6328d641ef3ecc8551d2c1fa/Team-LukOil-Racing-TurboLada-Samara-Ice-racer',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(163,'55785c5e30e293e03146b856dc99bd62','44d585f5-6359-4a74-8220-761d8f26f690','Turbo-Lada Samara /  C-C / VAZ 210893','The original Turbo-Lada Samara: A Lada Samara with a turbocharged engine and much added detail. Original by G-cars (bogdach) (www.drive3dautos.com). Features detailed lights, with fog lamps and running lights in the front bumper, plus two extra high beams, custom built roll cage, racing seats, some interior parts, complete engine, with a 2.0L 16v DOHC Engine with a big turbo, Small front mounted Intercooler, and many other details. 186 hp. Front wheel drive, 1150kg. It does not have very much power, but is very responsive, balanced and nimble, and has almost no turbolag over 2000 rpm. Fuel consumption: 8.5L/100km Bore: 92.75mm, Stroke: 74mm, Total capacity 1999cc, 185.8hp @5500, 298nm @ 2900 #2108 #bogdach #Car #charged #dw26 #gcars #intercooler #lada #racing #rally #rallye #rollcage #russian #samara #soviet #togliatti #turbo #uaz #vaz #volga # # # # # # # #',NULL,'lada',NULL,'samara',4.098160028457639826,1.855605959892270063,1.319244883488859931,NULL,NULL,'passenger','https://3dwarehouse.sketchup.com/model/55785c5e30e293e03146b856dc99bd62/TurboLada-Samara-CC-VAZ-210893',NULL,NULL,'{"VehicleType":null}');
