INSERT INTO CadModel VALUES(169,'412be1cef2a3d8e5e00e18b0cc00890d','44d585f5-6359-4a74-8220-761d8f26f690','AvtoVAZ Lada Riva','The VAZ-2105, VAZ-2104 and VAZ-2107 (collectively known as the Lada Riva in most Western European markets) are a series of medium-sized family cars built by Russian car manufacturer AvtoVAZ, introduced in 1980 in the Soviet Union, and progressively in other European markets through the early 1980s and sold in both saloon and estate versions. Today they are generally referred to as the Lada Classic series, being derived from the original Fiat 124 platform which has been the now-iconic mainstay of the AvtoVAZ lineup since the company''s foundation in the late 1960s. #80s #1980 #auto #avtovaz #car #communist #germany #lada #red #riva #russia #soviet #west',NULL,'lada',NULL,'riva',4.61337184906006037,1.780346393585209963,1.552953935228289951,'red',NULL,'passenger','https://3dwarehouse.sketchup.com/model/412be1cef2a3d8e5e00e18b0cc00890d/AvtoVAZ-Lada-Riva',NULL,NULL,'{"VehicleType":null}');
