INSERT INTO CadModel VALUES(225,'1e7f2b845ddf86c710c8a2e42abea40d','86abdf8bf5c42a1110c8a2e42abea40d','2012 Chevrolet Silverado Z71 LTZ 4X4 5.3L Shortbox','This is my 2012 Silverado LT 5.3L Z71offroad 4x4 SHORTBOX in black. it took a day to clean a model completely, change all the colors, build all new components(lights, rims, tires, bumper, grille, part of the hood, redo the windows and all the doors, the fenders, modify the box and tailgate, make a few bagdes, the Z71 decal) so as you can tell a lot of work went into this truck and its stil not done. i am going to add some gauge decals, as well as maybe trying to put inner components into the tailights like i did with the headlights. colormatch appearance package, 18 machined aluminum wheels, light cashmere and black interior tinted rear windows. all i ask is that you do not do stupid mods like 30 inch wheels or something, anything else is fine. please download, rate, and comment, and most of all enjoy! thanks to all and have a nice day!',NULL,'chevrolet','2012','silverado',5.374119281768799716,2.30871057510376021,1.939733115956189913,'black',NULL,'truck','https://3dwarehouse.sketchup.com/model/1e7f2b845ddf86c710c8a2e42abea40d/2012-Chevrolet-Silverado-Z71-LTZ-4X4-53L-Shortbox',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(226,'670049264e67de33afe717997470b28d','86abdf8bf5c42a1110c8a2e42abea40d','2012 Chevrolet Silverado Z71 4X4 LTZ 6.2L in summit white','i had to redo all the tags so i just copy some and addded some more. anyway, this is my 2012 Silverado LTZ 6.2L Z71offroad 4x4 in summit white. it took a day to clean a model completely, change all the colors, build all new components(lights, rims, tires, bumper, grille, part of the hood, redo the windows and all the doors, the fenders, modify the box and tailgate, make a few bagdes, the Z71 decal) so as you can tell a lot of work went into this truck and its stil not done. i am going to add some gauge decals, as well as maybe trying to put inner components into the tailights like i did with the headlights. colormatch appearance package, 18 machined aluminum wheels, light cashmere and black interior tinted rear windows. all i ask is that you do not do stupid mods like 30 inch wheels or something, anything else is fine. please download, rate, and comment, and most of all enjoy! thanks to all and have a nice day!',NULL,'chevrolet','2012','silverado',7.098443269729609816,2.611660003662109819,2.194119984284040203,'white',NULL,'truck','https://3dwarehouse.sketchup.com/model/670049264e67de33afe717997470b28d/2012-Chevrolet-Silverado-Z71-4X4-LTZ-62L-in-summit-white',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(227,'379f5cb65819ac2bafe717997470b28d','86abdf8bf5c42a1110c8a2e42abea40d','2012 Chevrolet S-10 Concept Ext. cab','Based on the chevrolet colorado, the s10 concept features a 4.3 Litre V6 Engine, an asthetics package and facelifted front end and rear end, as well as new rims. Nitto tires mounted on 17 inch aluminum alloy 5-spoke wheels give the all-terrain grip needed for offroading and everyday driving. heavy duty suspension components replace the stock parts to give added durability and offroad readiness. options include a chrome detail kit, 18 inch polished aluminum wheels, projector headlights, and much more.',NULL,'chevrolet','2012','s-10 concept',5.584513664245609909,2.274626493453979936,1.862225508317350008,'red',NULL,'truck','https://3dwarehouse.sketchup.com/model/379f5cb65819ac2bafe717997470b28d/2012-Chevrolet-S10-Concept-Ext-cab',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(228,'9b632a5bf9b7e631afe717997470b28d','86abdf8bf5c42a1110c8a2e42abea40d','My 1991 Chevy Cheyenne previous','this is the truck in its temporary stage. i made new mirrors because i got some new free stainless mirrors, i put my bubble mirror in the corner of the drivers mirror. i also scored some free gauges and mounted them where the ashtray goes. i fixed my tachometer and re-mounted it. truck will soon be UPDATED and re-uploaded with an interior and engine! please rate, download, and enjoy!',NULL,'chevrolet','1991','cheyenne',5.800656318664549894,2.25692737102508989,1.781566104851660005,'red',NULL,'truck','https://3dwarehouse.sketchup.com/model/9b632a5bf9b7e631afe717997470b28d/My-1991-Chevy-Cheyenne-previous',NULL,NULL,'{"VehicleType":null}');
