INSERT INTO CadModel VALUES(935,'u1bbb7182-00c9-47af-b4c4-89731ac70a2e','ub9801ba0-10f5-4950-88b3-db5ca5890d7f','International R190 Cement Truck','This rig is part of a massive fleet of trucks run by a local cement company. Although these trucks are old, they still work as hard as any modern truck, and when push comes to shove, they are often tougher. This truck ws built using two trucks created by chad3006, all the credit goes to him. Thanks!',NULL,'international',NULL,'r190',7.36081981658935991,2.46785998344420987,3.142427934333679839,'blue',NULL,'truck','https://3dwarehouse.sketchup.com/model/u1bbb7182-00c9-47af-b4c4-89731ac70a2e/International-R190-Cement-Truck',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(936,'uf41ce35c-fb22-4d43-a4cc-14aab332bda2','ub9801ba0-10f5-4950-88b3-db5ca5890d7f','1961 Mack B Model Well Drilling Truck','This  61 Mack has been upfitted with a drill rig for use of drilling water or oil wells. The truck also carries a modified pipe bumper and a recovery winch on the front. The truck belongs to Jake s Well Drilling Service. Thanks to JEXUP for the drilling apperatus, and chad3006 and CJ for the truck parts. Thnks to these and other contributors!',NULL,'mack','1961','b model',11.94972801208500001,2.873562812805179779,4.286663532257070308,NULL,NULL,'truck',NULL,NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(937,'u6760a0a8-7d15-4a10-92dd-5040fcd0a91e','ub9801ba0-10f5-4950-88b3-db5ca5890d7f','1955 International Harvester R190 Rigging Semi','This  55 IH R-series runs for J.H.Schritz Trucking and Rigging. This truck usually tows a special tri-axle gooseneck specifically built by S.W.Designs. The trailer is usually loaded with two smaller forklifts, and is the truck that is used the most for rigging jobs. Thanks to contributors!',NULL,'international','1955','r190',22.07145118713379973,2.873563289642329988,4.117592811662159847,NULL,NULL,'truck','https://3dwarehouse.sketchup.com/model/u6760a0a8-7d15-4a10-92dd-5040fcd0a91e/1955-International-Harvester-R190-Rigging-Semi',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(938,'ud6baa961-584d-4d71-abe2-5a95a83cab33','ub9801ba0-10f5-4950-88b3-db5ca5890d7f','1963 Mack B-Model Rigging Semi','This Model B Mack currently works for J.H.Schritz Trucking and Rigging, usually hauling the pictured flatbed trailer. This load consists of a traditional lathe, and a computerized CNC machine. Thanks to contributors!',NULL,'mack','1963','b model',19.85231208801269886,2.873562812805179779,3.60307550408864996,NULL,NULL,'truck',NULL,NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(939,'u538bb613-5b24-4b10-8137-4ea81d17f3c9','ub9801ba0-10f5-4950-88b3-db5ca5890d7f','1951 Diamond T 921 Rigging Semi','This truck currently runs for the company of J.H.Schritz Trucking and Rigging, and usually hauls this tri-axle lowboy and a larger forklift. Thanks to contributors!',NULL,'diamond t','1951','921',17.9057855606078995,2.873562932014470217,3.589982988456660084,NULL,NULL,'truck','https://3dwarehouse.sketchup.com/model/u538bb613-5b24-4b10-8137-4ea81d17f3c9/1951-Diamond-T-921-Rigging-Semi',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(940,'u5a2a977d-efd9-43cf-ad42-86e761642bf5','ub9801ba0-10f5-4950-88b3-db5ca5890d7f','1964 GMC Crackerbox Dual Steer Wrecker','This Gmc is a bit of a fluke. There are five Gmc dual steer trucks known to be in exsistence by this author, and at least two of them were tow trucks. The truck this model is based off of was known to work on the Alaskian Pipeline before being sold to a company in New Jersey. This truck is a part of the fleet at Jake s Garage, and goes under the name of  Big Jimmy , or truck number 05. Thanks to contributors!!',NULL,'gmc','1964','crackerbox',9.54847717285156073,2.873563170433039992,4.381185992386419593,'orange',NULL,'truck','https://3dwarehouse.sketchup.com/model/u5a2a977d-efd9-43cf-ad42-86e761642bf5/1964-GMC-Crackerbox-Dual-Steer-Wrecker',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(941,'uf2c5c481-138f-46aa-9101-2b6af8ffc039','ub9801ba0-10f5-4950-88b3-db5ca5890d7f','Big D Truck Pulling Team','This model is of  The Big D  pulling team vehicles. As stated elsewhere, the rig on the trailer is  The Big D (Dodge)  itself, a  76 Dodge D100 pulling truck. The tow vehicle is a  54 International R190 that has been modernized to pull the race truck and gear. Thanks to contributors! There were many, and unfortunatly, i do not recall all of thier names. Thank you!',NULL,NULL,NULL,NULL,12.64395856857299982,2.873563289642329988,2.688877825619699901,'yellow',NULL,'truck','https://3dwarehouse.sketchup.com/model/uf2c5c481-138f-46aa-9101-2b6af8ffc039/Big-D-Truck-Pulling-Team',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(942,'ea9158164ff297d01c2639aea037fbfc','ub9801ba0-10f5-4950-88b3-db5ca5890d7f','1959 Ford F250 Service Truck','This 1959 Ford F250 functions as the service truck for J.H.Schritz Trucking and Excavation, and as such is equipped to service anything from a tri-axle semi to a bulldozer. This equipment includes a spotlight and bed-mounted 1000lb capacity crane. Also in the bed is a diesel engine and a equipment tire, both pulled from failed machinery. Thanks to contributors!',NULL,'ford','1959','f-250',6.140486955642700195,2.326376557350160023,2.214623451232910156,'yellow',NULL,'truck','https://3dwarehouse.sketchup.com/model/ea9158164ff297d01c2639aea037fbfc/1959-Ford-F250-Service-Truck',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(943,'811a3807572ac908d98f385d687b7bd2','ub9801ba0-10f5-4950-88b3-db5ca5890d7f','1954 IH R190 and Cat D9 Bulldozer','Here it is! This was my idea: J.H.Schrtiz Trucking and Excavation. This is my  54 International dump truck, pulling a equipment trailer loaded with a Cat D9 dozer. The Cat was made by SK u03a3TCHUP C u00d8U u0419TY SH u03a3 u042fIFF, but i had remotor it to get it to fit: it now has pete1993 s latest diesel engine. Thanks to all contributors!',NULL,'international','1954','r190',17.89464759826660156,2.873563289642329988,3.745877742630280061,NULL,NULL,'truck','https://3dwarehouse.sketchup.com/model/811a3807572ac908d98f385d687b7bd2/1954-IH-R190-and-Cat-D9-Bulldozer',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(944,'b676b30ea875a1d89d7bd6424ef39284','ub9801ba0-10f5-4950-88b3-db5ca5890d7f','1954 IH R190 Dump Truck','This 1954 IH R190 is actually a representation of a truck in my local junkyard. I have a half a mind to get it and fix it up, maybe use it to make a little money? Hey, that gives me an idea.. Stay tuned. Thanks to contributors!',NULL,'international','1954','r190',6.597499847412110264,2.518320083618160066,2.751480102539059835,NULL,NULL,'truck','https://3dwarehouse.sketchup.com/model/b676b30ea875a1d89d7bd6424ef39284/1954-IH-R190-Dump-Truck',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(945,'16e5119ed98b6956bd17d3757ed1e0f2','ub9801ba0-10f5-4950-88b3-db5ca5890d7f',' ','This 1953 International Harvester R190 is set up as a mobile crane, and is run by a company called Jake s Crane Service. I used Coolbean s crane mounted to Chad3006 s truck, which i stretched into a tandem axle. I had a lot of fun on this cool project, i think its one of my favorites! Thanks to all contributors!',NULL,'international',NULL,'r190',9.201406955718990588,2.873563289642329988,3.594725608335629819,NULL,NULL,'truck','https://3dwarehouse.sketchup.com/model/16e5119ed98b6956bd17d3757ed1e0f2/',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(946,'87342b2f669c6bb1c8760fa3f1cd98d4','ub9801ba0-10f5-4950-88b3-db5ca5890d7f','1949 Chevy Wrecker','This 1949 Chevy wrecker is the fourth truck in the Jake s Garage fleet. This truck fills in for the  59 Ford, and tends to smaller towing jobs. However, when the stuff hits the fan, this medium-duty wrecker is more than capable to assist the bigger trucks. Thanks to all contributors!',NULL,'chevrolet','1949',NULL,7.57862424850463956,2.873563289642329988,2.80784368506150983,'orange',NULL,'truck','https://3dwarehouse.sketchup.com/model/87342b2f669c6bb1c8760fa3f1cd98d4/1949-Chevy-Wrecker',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(947,'1c7931cbfab15be66660ffd722d94212','ub9801ba0-10f5-4950-88b3-db5ca5890d7f','1954 Diamond T 921 Wrecker','This 1954 Diamond T is the third truck of the Jake s Garage fleet, and functions as the Heavy Recovery Unit, handling the big jobs that come the company s way. This tandem axle cabover is equipped with a Holmes wrecking unit, as are the others. Thanks to contributors!',NULL,'diamond t','1954','921',7.352910518646240235,2.873563289642329988,3.02831268710772017,NULL,NULL,'truck','https://3dwarehouse.sketchup.com/model/1c7931cbfab15be66660ffd722d94212/1954-Diamond-T-921-Wrecker',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(948,'8cb9b518e1af196c6660ffd722d94212','ub9801ba0-10f5-4950-88b3-db5ca5890d7f','1959 Ford F250 Wrecker','This two-tone F250 sports a Holmes wrecker mounted in it s bed. This truck runs as number two of the Jake s Garage fleet, and is used for lighter jobs, such as towing broken down cars. Thanks to contributors!',NULL,'ford','1959','f-250',6.042481899261470168,2.183907985687259857,2.154753446445869969,'orange',NULL,'truck','https://3dwarehouse.sketchup.com/model/8cb9b518e1af196c6660ffd722d94212/1959-Ford-F250-Wrecker',NULL,NULL,'{"VehicleType":null}');
