INSERT INTO CadModel VALUES(967,'7b49cdd8dc7e1a9356691ea7615d9897','uc5e2db3a-f69c-410a-aae7-8208d0fba9fd','1989 PAZ 3205','Pavlovsky Avtobusny Zavod is a manufacturer of buses in Russia, located in the city of Pavlovo, Nizhny Novgorod Oblast. The building of the factory started in 1952, and in the same year the first buses PAZ-651 (based on GAZ-51) were produced. The government had a plan to produce 10,000 buses per year. In 1960, the production of new model PAZ-652 started. It was replaced by PAZ-672 in early 1968, and this bus had a large family of various modifications. 1989 saw a start of production of the new modernized model PAZ-3205. #1990s #3205 #Automobile #Bus #Car #Coach #Huge #PAZ #PAZ3205 #Russian #Stock #Transport #Transportation #Truck #Vehicle',NULL,'paz','1989','3205',6.477645397186280186,2.780146121978760209,2.669630863238130037,'gray',NULL,'bus','https://3dwarehouse.sketchup.com/model/7b49cdd8dc7e1a9356691ea7615d9897/1989-PAZ-3205',NULL,NULL,'{"VehicleType":null}');
