INSERT INTO CadModel VALUES(991,'5ee9f5327e268d51d997eabfc0fb7788','uc5e2db3a-f69c-410a-aae7-8208d0fba9fd','Isuzu NKR-55','My firstever real 3D model with SketchUp. I created it only to support my job designing special utility vehicles, at which my big concern laid only in the precision of the wheelbase, the trackwidth and the chassis frame dimensions... #commercial_truck #isuzu #NKR55 #truck',NULL,'isuzu',NULL,'nkr 55',5.820880174636839933,1.889999985694889917,2.160490036010739968,NULL,NULL,'truck','https://3dwarehouse.sketchup.com/model/5ee9f5327e268d51d997eabfc0fb7788/Isuzu-NKR55',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(992,'231edf2ae4bae68b4c2c88971423d0be','uc5e2db3a-f69c-410a-aae7-8208d0fba9fd','KrAZ-6322','The KrAZ-6322 (63221 type 1) all-wheel drive off-road chassis is designed for mounting of special heavy manufacturing equipment as well as construction, municipal and oil and gas equipment.  The vehicle successfully operates on hard-surfaced roads including cobblestone, crushed-stone surfaced and earth roads in harsh environmental, weather and road conditions.  On the customers demand, the chassis can be equipped with various cabs such as two-door three-seat, four-door seven-seat or two-door with berth, winch with tractive force up to 12 t designed for self-recovery and recovery of stuck vehicles as well as ABS, starting preheater, and air conditioning.  The chassis is available with single or double tyres with a centralized tyre inflation system ensuring high cross-country ability on low-load-bearing capacity soils.',NULL,'kraz',NULL,'6322',9.22494029998778941,2.801739931106570048,3.237829923629759855,NULL,NULL,'truck','https://3dwarehouse.sketchup.com/model/231edf2ae4bae68b4c2c88971423d0be/KrAZ6322',NULL,NULL,'{"VehicleType":null}');
