INSERT INTO CadModel VALUES(1034,'793bf92e46e3bf26ee97dca9bbab9078','uecadcbca-a400-428d-9240-a331ac5014f6','Thomas Built Freightliner FS-65','This is a Thomas Built freightliner FS-65 with a 5 speed manual transmition The Freightliner FS-65 is a Type C conventional bus chassis manufactured by Freightliner, used for school bus and commercial bus applications. It was introduced for the 1997 model year for Thomas Built Buses. The FS-65 is most closely related to Freightliner s FL-Series medium-duty conventional.',NULL,'thomas built buses',NULL,'fs-65',10.54000663757319955,2.873563170433039992,2.658436065192399944,NULL,NULL,'bus','https://3dwarehouse.sketchup.com/model/793bf92e46e3bf26ee97dca9bbab9078/Thomas-Built-Freightliner-FS65',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(1035,'92bf837e546da42abc7f39bf011e847f','uecadcbca-a400-428d-9240-a331ac5014f6','1966-1972 Gillig Bros. Transit Coach, WA-spec','This is a model of a 1966-1972 Gillig Bros. Transit Coach, based off of a 1966 Gillig school bus I own. It is detailed throughout with a fully detailed instrument panel and a full twelve rows of seats. Model updated November 17 to reflect missing inaccuracies. Those include mirrors (exterior and the interior rear view), full exhaust system and rear mudflaps. I ve also added the GILLIG logo text to the exterior emblems, and added the missing interior emblem.',NULL,'gillig','1966',NULL,11.10867977142330077,2.73354005813598988,3.479190111160280096,'yellow',NULL,'bus','https://3dwarehouse.sketchup.com/model/92bf837e546da42abc7f39bf011e847f/19661972-Gillig-Bros-Transit-Coach-WAspec',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(1036,'2f77c7fc777f8b11665c5daec82c51b2','uecadcbca-a400-428d-9240-a331ac5014f6','School Bus with interior','This is a CX-4500 Regal Coach. This bus includes LED headlamps, reflective crossing guard, LED warning lights, LED stop sign, deluxe passenger seating, chrome finishes(wheels, grille, bumper,mirrors), luggage compartments, interior luggage racks(above seats), extra wide aisles, dual upper emergency exits, premier sealed windows, deluxe climate control, along with many driver features. This bus sells for approximately $165,000.',NULL,NULL,NULL,NULL,13.1447601318359002,2.873563051223749998,3.256435871334450117,'yellow',NULL,'bus','https://3dwarehouse.sketchup.com/model/2f77c7fc777f8b11665c5daec82c51b2/School-Bus-with-interior',NULL,NULL,'{"VehicleType":null}');
