INSERT INTO CadModel VALUES(1055,'5cad4774f1de2f9ebe40bb45ea25a041','91f36aacbde112e168742254bcf1c9e9','Albany Presidente (GTA IV) (250th Model)','The Albany Presidente is a four-door luxury sports sedan found in Grand Theft Auto IV. The Presidente is largely based on the first generation Cadillac CTS, though the headlights resemble those of the second generation CTS, albeit widened. The Presidente''s 4.5 L (275 cu in) V10 engine is coupled to a 5 speed gearbox in a RWD configuration. Acceleration is fair, but, due to its weight, the Presidente has a top speed of 188 mph (302 km/h). Handling is fair, but suffers from mild under-steer due to the up-front weight of the heavy engine. The suspension is somewhat soft, being able to absorb all the bumps on the road, but it does provide heaps of body roll. Braking is above average, and ABS is standard across the line-up. Crash deformation is surprisingly poor for this vehicle, and after one to two crashes it is known to pull to one side. The engine is somewhat sturdy and can survive a few impacts before failing. I imported this from a GTA SA file using Zmodeler 2 and exported it to 3ds and imported it to SketchUp, regrouped and coloured everything. Fully detailed. Logo by hitman86. Please rate!',NULL,NULL,NULL,NULL,4.91324853897094993,1.905236244201659934,1.489669522969049975,'blue',NULL,'passenger','https://3dwarehouse.sketchup.com/model/5cad4774f1de2f9ebe40bb45ea25a041/Albany-Presidente-GTA-IV-250th-Model',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(1056,'879d974ec5d4eb0dfe97516c7eaf86b3','91f36aacbde112e168742254bcf1c9e9','2012 Mercedes-Benz C63 AMG Coup Black Series C204','Available in Coup body, it includes an upgraded version of C 63 AMG engine rated 517 PS (380 kW; 510 hp) @6800rpm and 620 Nm (457 lbft) @5000rpm, zero to 100 km/h in 4.2 seconds acceleration, 255/35 R 19 and 285/30 R 19 wheels, black diffuser insert from SLS AMG GT3, chromed twin tailpipes, AMG sports suspension with AMG rear axle differential lock, 3-stage ESP, two AMG sports bucket seats and much more. Mercedes wanted to built only 650 units, but after the success, they have built 800 units.',NULL,'mercedes-benz','2012','amg c 63 coupe',4.497300624847410333,1.892393946647640047,1.366742491722110042,'red',NULL,'passenger','https://3dwarehouse.sketchup.com/model/879d974ec5d4eb0dfe97516c7eaf86b3/2012-MercedesBenz-C63-AMG-Coup-Black-Series-C204',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(1057,'fc557e5f16bff94bfe97516c7eaf86b3','91f36aacbde112e168742254bcf1c9e9','2012 Mercedes-Benz C63 AMG Coup Black Series C204','Available in Coup body, it includes an upgraded version of C 63 AMG engine rated 517 PS (380 kW; 510 hp) @6800rpm and 620 Nm (457 lbft) @5000rpm, zero to 100 km/h in 4.2 seconds acceleration, 255/35 R 19 and 285/30 R 19 wheels, black diffuser insert from SLS AMG GT3, chromed twin tailpipes, AMG sports suspension with AMG rear axle differential lock, 3-stage ESP, two AMG sports bucket seats and much more. Mercedes wanted to built only 650 units, but after the success, they have built 800 units.',NULL,'mercedes-benz','2012','amg c 63 coupe',4.750453472137450284,1.998916745185850053,1.443673790432510096,'white',NULL,'passenger','https://3dwarehouse.sketchup.com/model/fc557e5f16bff94bfe97516c7eaf86b3/2012-MercedesBenz-C63-AMG-Coup-Black-Series-C204',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(1058,'5d9f3d3e2f859d2f322edd0914d508b2','91f36aacbde112e168742254bcf1c9e9','Chrysler LX 300C','The Chrysler 300 is a full-size sedan first shown at the 2003 New York Auto Show as a concept car. Sales in the U.S. began in the spring of 2004 as an early 2005 model year car. A redesigned 300 was introduced in 2011. Only the sedan body-style is available; the station wagon version of the 300 has been discontinued. Exterior changes include a revised body, bi-xenon HID projector headlights, LED daytime running strips within the headlights, modified tail lights with LEDs and a horizontally slotted front grille. Original by mandun. Wheels by Mitchieboy. 2012',NULL,'chrysler',NULL,'300',4.714728832244870382,1.96285653114319003,1.432366270571949985,'white',NULL,'passenger','https://3dwarehouse.sketchup.com/model/5d9f3d3e2f859d2f322edd0914d508b2/Chrysler-LX-300C',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(1059,'9ed7a5150e0c473ed5e91de406e3735b','91f36aacbde112e168742254bcf1c9e9','2014 Bellyard Beleaguer','The second generation Bellyard Beleaguer, lacking interior. Some of my best work with exterior work was included in the design of this vehicle. If anyone wishes to design an interior for me, that would be great. However, I''m also working on one myself. #2013 #Beleaguer #Bell #Bellemonte #Bellyard #Beluga #car #company #fictional #KeiTrekker #new #Outdoorsman #Yard','other',NULL,'2014','beleaguer',5.297036170959469991,5.281527280807499559,1.545136451721190074,NULL,NULL,'passenger','https://3dwarehouse.sketchup.com/model/9ed7a5150e0c473ed5e91de406e3735b/2014-Bellyard-Beleaguer',NULL,NULL,'{"VehicleType":null}');
