INSERT INTO CadModel VALUES(1063,'1e4690dbd2d041c04c2c88971423d0be','91f36aacbde112e168742254bcf1c9e9','Ural-4320','The Ural-4320 is a general purpose off-road 6x6 truck, produced at the Ural Automotive Plant in Miass, Russia for use in the Russian army. Introduced in 1976, it is still in production today. The wheel arrangement for the Ural-4320 was designed for transporting cargo, people and trailers on all types of roads and terrain. It also serves as a launching platform for the BM-21 Grad rocket launcher.  The Ural-4320 is a diesel-powered development of the Ural-375D. The Ural-4320 chassis has good ground clearance, so it is preferred in regions where roads are difficult to traverse due to sand or big rocks. In the proverbial Russian tradition, the Ural-4320 is reliable and easy to repair and maintain. It has civilian uses as a fire truck, a garbage truck, or a logging truck. It is also used for water, oil and gas drilling using the 1BA15 and URB-3A3 drilling rigs, which are mounted on the Ural-4320 chassis. #4320 #armour #army #dump #kamaz',NULL,'ural',NULL,'4320',9.2406196594238299,3.45673000812531006,3.300829887390139828,'gray',NULL,'truck','https://3dwarehouse.sketchup.com/model/1e4690dbd2d041c04c2c88971423d0be/Ural4320',NULL,NULL,'{"VehicleType":null}');
