INSERT INTO CadModel VALUES(1072,'7fd710a1f5d703acf95c06119540a20c','91f36aacbde112e168742254bcf1c9e9','2007 Chrysler Aspen (v2.0)','A 2007 Chrysler Aspen. The original model was ripped from the game Splinter Cell Conviction, and rebuilt from the ground up when it was found that the model''s axes and UV maps were screwed up. I ripped the model, built the wheels, most of the interior trim, the front fascia, the badges, and the switches and buttons of the dash. The rest was handled by a member of Ubisoft''s modeling team some three years ago. I will continue to iron the bugs out on this model as I go along. What this is meant to be is a port from Splinter Cell to the game Garry''s mod, as a drivable vehicle. Credit: Ubisoft Montreal: making the model in the first place ZombieRoboNinja: Ripping, rescaling, rebuilding, and de-generifying the model  Updates for Version 2.0:   -Smoothgroups applied.  -Dash Rebuilt (again) -Doors are separate (and solid) components -Shading Updated -3rd row seat added -speakers added -engine bay added/simple engine added(will be updated) -New steering wheel -center consoles updated -towing package installed (will add hitch in v.2.1 or v3.0) -Headlamps Rebuilt  updates planned for v.3.0:  -Trailer hitch attachment -Engine update -rear floor-based cargo compartment addition -flip down sun shades -roof console additions -support handles for second-row seats  more suggestions welcome! #2007 #300',NULL,'chrysler','2007','aspen',5.517600059509280008,2.403520107269290217,2.20960462326184004,'gray',NULL,'passenger','https://3dwarehouse.sketchup.com/model/7fd710a1f5d703acf95c06119540a20c/2007-Chrysler-Aspen-v20',NULL,NULL,'{"VehicleType":null}');
