INSERT INTO CadModel VALUES(1074,'15bbcc80fac69259e9836bd428f79b0b','91f36aacbde112e168742254bcf1c9e9','VW Bora','Production of the fourth generation car began in July 1999.[55] Carrying on the wind nomenclature, the car was known as the Volkswagen Bora in much of the world. Bora is a winter wind which blows intermittently over the coast of the Adriatic Sea, as well as in parts of Greece, Russia, Turkey, and in the Sliven region of Bulgaria. In North America and South Africa, the Jetta moniker was again kept on due to the continued popularity of the car in those markets.',NULL,'volkswagen','1999','bora',3.943405628204350144,1.821205377578740014,1.511287292465570032,'white',NULL,'passenger','https://3dwarehouse.sketchup.com/model/15bbcc80fac69259e9836bd428f79b0b/VW-Bora',NULL,NULL,'{"VehicleType":null}');
