INSERT INTO CadModel VALUES(1081,'f34c03711c3fc44ac10e9d4ee4bae4f4','91f36aacbde112e168742254bcf1c9e9','2006 Opel GT','On February 1, 2006, Opel issued a press release announcing the upcoming production of a new Opel GT, as a likely 2007 model. The car shares the GM Kappa platform with the Pontiac Solstice and the Saturn Sky. Unlike its platform mates, the 2.0 L, 260 hp (194 kW; 264 PS) direct injection turbocharged Ecotec four-cylinder engine was the only engine offered. It also featured 18-inch alloy wheels and a folding cloth top similar to those found on the Solstice and the Sky. Since GM''s Saturn division already shared models with Opel, the GT is in fact Opel''s version of the Saturn Sky. The car replaced the Opel Speedster in the European lineup; however, it was not sold in right-hand drive in the UK, thus there is no replacement for the Vauxhall VX220. The situation is similar to Holden in Australia, as the Saturn Sky and Pontiac Solstice had been produced at a North American plant, which does not have the necessary tooling for producing right-hand drive vehicles.',NULL,'opel','2006','gt',3.953761816024779829,1.9463475942611701,1.134761119261380013,'black',NULL,'passenger','https://3dwarehouse.sketchup.com/model/f34c03711c3fc44ac10e9d4ee4bae4f4/2006-Opel-GT',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(1082,'58264758e357d7d04c2c88971423d0be','91f36aacbde112e168742254bcf1c9e9','Kraz C18.1','The KrAZ C18.1 dump truck is used for transporting loose materials on hard-surface roads including cobblestone and macadam pavement, as well as earth roads. The vehicle is provided with bonnet made of single panel that allows fitting both cylinder in-line and V-engines. #4x2 #4x4 #6x4 #6x6 #8x4 #8x6 #8x8 #big #chassis #dumb #el_mariano #kraz #kremenchug #offroad #truck #ukraine #ussr #vehicle # # #',NULL,'kraz',NULL,'c18.0',8.880479812622070313,2.801739931106570048,3.400190114974980027,NULL,NULL,'truck','https://3dwarehouse.sketchup.com/model/58264758e357d7d04c2c88971423d0be/Kraz-C181',NULL,NULL,'{"VehicleType":null}');
