INSERT INTO CadModel VALUES(1085,'59eda4e7e802f1d3f0cbbde4f6cf4fb4','91f36aacbde112e168742254bcf1c9e9','Chevrolet Volt 2012','The Chevrolet Volt is a plug-in hybrid electric vehicle manufactured by General Motors, and also sold as the Opel/Vauxhall Ampera in Europe, and marketed as the Holden Volt in Australia and New Zealand. Volt sales in the U.S. began in mid-December 2010 and in international markets since September 2011. Customer deliveries of the Opel Ampera in Europe began in February 2012, and the Vauxhall Ampera was released in the U.K. in May 2012.','triangles','chevrolet','2012','volt',4.112666606903079725,1.956041455268860086,1.593462044373149977,NULL,NULL,'passenger','https://3dwarehouse.sketchup.com/model/59eda4e7e802f1d3f0cbbde4f6cf4fb4/Chevrolet-Volt-2012',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(1086,'f8dc466677c26ac6f63ee8a34069b7c5','91f36aacbde112e168742254bcf1c9e9','Emperor Habanero (GTA IV)','The Emperor Habanero is a mid-size crossover SUV found in Grand Theft Auto IV. The Habanero appears to be based primarily off of the 2004-2009 Lexus RX (a rebadge of the Japanese Toyota Harrier), but it is slightly bulkier, resembling the Toyota Venza. Like the Lexus, the Habanero doesn''t do well off road due to its low ground clearance, and is more sport-oriented and features a slightly porky curb weight (for a small SUV). However, the Habanero is good for cruising around Liberty City.It may have the taillights reasembling 2005-2007 Mitsubishi Outlander''s taillights. The interior of the vehicle bears the a likeness to that of an Imponte DF8-90. I imported this from a GTA: SA file using Zmodeler 2 and exported it to 3ds and imported it to SketchUp, regrouped and recolored some parts. Please rate! #auto #car #emperor #grand #gta #habanero #iv #lexus #midsize #rx #suv #theft #xrw960h',NULL,NULL,NULL,NULL,4.879008293151859909,1.90998423099518,1.813416981603950041,'white',NULL,'passenger','https://3dwarehouse.sketchup.com/model/f8dc466677c26ac6f63ee8a34069b7c5/Emperor-Habanero-GTA-IV',NULL,NULL,'{"VehicleType":null}');
