INSERT INTO CadModel VALUES(1100,'d471c4f43f008df5c1bcae9def1986da','91f36aacbde112e168742254bcf1c9e9','Toyota IMV Hilux V','The Toyota Hilux is a series of compact pickup trucks produced and marketed by the Toyota Motor Corporation. Most countries used the Hilux name for the entire life of the series but in North America, the Hilux name was retired in 1976 in favor of Truck, Pickup Truck, or Compact Truck. In North America the popular option package, the SR5 (Sport Rally 5-Speed), was colloquially used as a model name for the truck, even though the option package was also used on other Toyota models like the Corolla. In 1984, the Trekker, the camper version of the Hilux, was renamed as the 4Runner in Australia and North America, and as the Hilux Surf in Japan. In 1995, Toyota introduced a new pickup model, the Tacoma in the United States, discontinuing the Hilux/Pickup there. The 4Runner is now a full SUV, and the more recent models do not resemble the Tacoma. Original by renato. I cleaned it up. Rims by xrw960h. Running boards byPETERBILT1993. 2012',NULL,'toyota',NULL,'hilux',5.412640094757080078,2.189620018005370205,1.83193016052246005,'white',NULL,'truck','https://3dwarehouse.sketchup.com/model/d471c4f43f008df5c1bcae9def1986da/Toyota-IMV-Hilux-V',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(1101,'2e3fd53a27e3f28ce5b70ae3b05b59e9','91f36aacbde112e168742254bcf1c9e9','Gooseneck Boat Trailer and Truck','This Ford F-350 Lariat is towing a modified 50'' Gooseneck Flatbed redesigned for use as a boat trailer. On the trailer are two boats, a Marine Patrol boat as well as a small sailboat (sail removed). Thanks to all the contributers for helping me with this model. #Boat #Boat_Hauler #Boat_Shipping #Boat_Trailer #Boat_Transport #Ford_F350 #Gooseneck #Gooseneck_Boat_Trailer #Gooseneck_Trailer #Heavy_Hauling #Maritime_Transportation #Sailboat #Shipping_Wars #Trailer #UShip',NULL,'ford',NULL,'f-350',20.50237369537349962,2.763675570487980071,4.093094926327469629,NULL,NULL,'truck','https://3dwarehouse.sketchup.com/model/2e3fd53a27e3f28ce5b70ae3b05b59e9/Gooseneck-Boat-Trailer-and-Truck',NULL,NULL,'{"VehicleType":null}');
