INSERT INTO CadModel VALUES(1133,'bc1f5cf1f280065ce071bb57038d698c','91f36aacbde112e168742254bcf1c9e9','Fahrzeuge - Ford Taurus SHO 2010','Der Ford Taurus ist ein Automodell der US-amerikanischen Automobilfirma Ford. Nach US-amerikanischen Mastben ist der Taurus als Mittelklassemodell einzuordnen. Seit 1986 wurde er bisher in vier Baureihen produziert. Den Ford Taurus gibt es als Limousine, bis 2007 wurde er auch in einer Kombiversion angeboten. Die Sportversion wird als Taurus SHO bezeichnet. Das weitgehend baugleiche Modell der Ford-Konzernmarke Mercury trgt die Bezeichnung Sable. Mitte 2009 wurde die mittlerweile sechste Generation des Taurus auf dem US-Markt eingefhrt.',NULL,'ford','2010','taurus',4.78206300735473988,2.001831769943239969,1.497463477775450081,NULL,NULL,'passenger','https://3dwarehouse.sketchup.com/model/bc1f5cf1f280065ce071bb57038d698c/Fahrzeuge-Ford-Taurus-SHO-2010',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(1134,'a6ea039acdff728e071bb57038d698c','91f36aacbde112e168742254bcf1c9e9','Fahrzeuge - Ford Fusion Sport 2010','Der Ford Fusion ist ein Pkw-Modell der Mittelklasse, das seit 2005 von der amerikanischen Ford Motor Company hergestellt wird. Der Fusion ist der Nachfolger des Ford Contour und basiert auf einer verlngerten Bodengruppe des Mazda 6. Er ist innerhalb der Modellpalette zwischen den Modellen Ford Focus und Ford Taurus platziert. Mit dem Fusion weitgehend baugleich sind der Mercury Milan und der Lincoln MKZ (ehemals Zephyr). Der amerikanische Ford Fusion ist nicht zu verwechseln mit dem gleichnamigen europischen Modell, das auf dem Ford Fiesta V (20012008) basiert. Der berarbeitete Fusion wird seit Mrz 2009 auf dem US-Markt angeboten.',NULL,'ford','2010','fusion',4.875820636749270242,2.04638600349426003,1.682251507183539995,NULL,NULL,'passenger','https://3dwarehouse.sketchup.com/model/a6ea039acdff728e071bb57038d698c/Fahrzeuge-Ford-Fusion-Sport-2010',NULL,NULL,'{"VehicleType":null}');
