INSERT INTO CadModel VALUES(1144,'6d296f7fae3f7f34981c1fca8c617850','91f36aacbde112e168742254bcf1c9e9','Vehicles - VW Passat B6 R36','The latest B6 Passat was first displayed at the Geneva Motor Show in March 2005, and launched in Europe in the summer of 2005. The Mk6 Passat (the PQ46 platform) is now based upon the platform from the Golf Mk5. This model is sometimes referred to as the B6 (or 3C) Passat, despite its lack of commonality with the B6 (Typ 8E) Audi A4. This has happened previously in the Passat''s history, with the B3 and B4, which bore no relation to the same-named platforms from Audi. The R36 uses a 3.6 litre VR6 engine, retuned to produce 300 PS (221 kW; 296 bhp), and 350 newton metres (258 ftlbf) of torque, which Volkswagen claim pushes the saloon and Variant (estate/wagon) to 100 km/h (62.1 mph) in 5.6 and 5.8 seconds respectively. Reworked version of my B6 Passat - different bumpers, cleaned Chassis, details added #cleaned_Chassis #details_added','matte glass','volkswagen','2005','passat',4.959384441375729757,2.108453750610349787,1.543121463153509953,'black',NULL,'passenger','https://3dwarehouse.sketchup.com/model/6d296f7fae3f7f34981c1fca8c617850/Vehicles-VW-Passat-B6-R36',NULL,NULL,'{"VehicleType":null}');
