INSERT INTO CadModel VALUES(1147,'6214781d0b8dc5dcd24940860aca4efe','91f36aacbde112e168742254bcf1c9e9','Vehicles - Toyota Alphard 1st Generation','The Toyota Alphard is a luxury MPV produced by the Japanese automaker Toyota since 2002. It is available as a seven or eight-seater with 2.4 and 3.0-litre gasoline engines in 3 different model lines - Alphard G, Alphard V and Alphard Hybrid. The Alphard is primarily made for the Japanese market, but is also sold in Indonesia, Hong Kong, Bangladesh, Singapore, Thailand,[2] and Malaysia. The vehicle was named after the Alphard, the brightest star in the constellation Hydra.',NULL,'toyota','2002','alphard',5.19429540634155007,2.285325765609739878,2.066455841064450017,'white',NULL,'passenger','https://3dwarehouse.sketchup.com/model/6214781d0b8dc5dcd24940860aca4efe/Vehicles-Toyota-Alphard-1st-Generation',NULL,NULL,'{"VehicleType":null}');
