INSERT INTO CadModel VALUES(1152,'6588848b5f471baeed5c7db9ee2071f0','91f36aacbde112e168742254bcf1c9e9','Vehicles - Lotus Elise S2','The Lotus Elise is a two seat, rear-wheel drive, mid-engined roadster conceived in early 1994 and released in September 1996 by the English manufacturer Lotus Cars. The car has a hand-finished fibreglass body shell atop its extruded aluminium and bonded chassis that provides a rigid platform for the suspension, while keeping weight and production costs to a minimum. The roadster is capable of speeds up to 240 km/h (150 mph). The Elise was named after Elisa, the granddaughter of Romano Artioli who was chairman of Lotus at the time of the car''s launch.','other','lotus','1996','elise',5.087357997894289773,4.82634639739989968,1.322500263806430043,'red',NULL,'passenger','https://3dwarehouse.sketchup.com/model/6588848b5f471baeed5c7db9ee2071f0/Vehicles-Lotus-Elise-S2',NULL,NULL,'{"VehicleType":null}');
