INSERT INTO CadModel VALUES(1154,'3f16d6ac013aa946977e464a4b82757d','91f36aacbde112e168742254bcf1c9e9','Vehicles - Hummer H2 SUT','The Hummer H2 is an SUV and SUT sold by General Motors under the Hummer brand.[1][2] It is a large truck (lighter and slightly slimmer than the Hummer H1, while slightly longer and slightly taller) with room for six passengers (including driver). The rearmost part of the H2 SUV was modified to a pickup truck bed for the 2005 H2 SUT (Sport Utility Truck).',NULL,'hummer',NULL,'h2',5.140710353851320136,2.535335779190059924,2.101591971237210199,'yellow',NULL,'passenger','https://3dwarehouse.sketchup.com/model/3f16d6ac013aa946977e464a4b82757d/Vehicles-Hummer-H2-SUT',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(1155,'8c88dfc599633110c2e85e9572fadc63','91f36aacbde112e168742254bcf1c9e9','Vehicles -Nissan Pathfinder R51','The Nissan Pathfinder and Terrano were originally compact SUVs and they are now mid-size SUVs. Whereas the Pathfinder is sold in North America, the name first introduced in late 1986, elsewhere in the world the vehicle was known as the Terrano. The first generation Pathfinder/Terrano platform is known as the WD21. The second generation Pathfinder platform is known as the R50, and the third generation is known as the R51. The Pathfinder is slotted in size between the Murano and Armada or Patrol, but in price between the Xterra and Murano.',NULL,'nissan',NULL,'pathfinder',5.340461254119870383,2.295867919921870115,1.899370613507930017,NULL,NULL,'passenger','https://3dwarehouse.sketchup.com/model/8c88dfc599633110c2e85e9572fadc63/Vehicles-Nissan-Pathfinder-R51',NULL,NULL,'{"VehicleType":null}');
