INSERT INTO CadModel VALUES(1157,'a4879976203c2e6fca3a0ccb5e93bbb','91f36aacbde112e168742254bcf1c9e9','Vehicles -Volvo XC90','The Volvo XC90 is a large-size luxury crossover SUV produced by Volvo Cars since it was unveiled at the Detroit Motor Show 2002. It is based on the P2 platform, shared with the first generation Volvo S80 and other large Volvo cars. As Volvo''s top-selling vehicle in the United States, the XC90 is also Volvo''s best selling model worldwide with 85,994 cars sold in 2005.',NULL,'volvo','2002','xc90',4.796290397644040304,1.971026659011839933,1.854393379762770078,'gray',NULL,'passenger','https://3dwarehouse.sketchup.com/model/a4879976203c2e6fca3a0ccb5e93bbb/Vehicles-Volvo-XC90',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(1158,'2d50553277d64ebda513de4eb79b310d','91f36aacbde112e168742254bcf1c9e9','Bikes - Yamaha Vmax','The Yamaha V-Max is a motorcycle manufactured by Yamaha, which is known for its powerful V4 engine, shaft drive, and distinctive styling. While famed for its quick acceleration, it is often criticized for its poor cornering ability and soft suspension.',NULL,'yamaha',NULL,'vmax',2.463740110397340199,1.039450049400330033,1.363467223942280037,NULL,NULL,'bike','https://3dwarehouse.sketchup.com/model/2d50553277d64ebda513de4eb79b310d/Bikes-Yamaha-Vmax',NULL,NULL,'{"VehicleType":null}');
