INSERT INTO CadModel VALUES(1163,'7db6c18d976e52e451553ea674d2701f','91f36aacbde112e168742254bcf1c9e9','2006 Volkswagen Phaeton W12 Diesel','It is the STOCK model of the Phaeton, not tuned. The Phaeton was the idea of Volkswagen chairman Ferdinand Pich. Pich wanted VW engineers to create a car that would overwhelmingly surpass the prestige market leaders, Mercedes Benz and BMW. The decision to release the Phaeton was, in part, a response to Mercedes'' decision to compete directly with VW in the European marketplace with the low-cost A-Class.It was originally uploaded by =FJC=. Warning: some of my models will be uploaded, so you''ll have to look at the back of all my model pages to find the reuploaded cars. #Automobile #AWD #Car #Germany #Phaeton #Saloon #Sedan #V10 #V6 #V8 #Vehicle #Volkswagen #VW #W12','triangles','volkswagen','2006','phaeton',5.344639778137209696,2.175679922103880059,1.529019951820369982,'black',NULL,'passenger','https://3dwarehouse.sketchup.com/model/7db6c18d976e52e451553ea674d2701f/2006-Volkswagen-Phaeton-W12-Diesel',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(1164,'bbb89eca7fed0cdb872192610795619a','91f36aacbde112e168742254bcf1c9e9','Chevy Silverado 4-door pick-up truck','A detailed 3D model of a Chevy Silverado or GM 4-door pick-up truck from Antics Technologies. An interactive version of this truck can be downloaded from the Antics Content Warehouse at www.antics3d.com for use within Antics3D animation software, side-by-side with your SketchUp architectures and props. The Antics3D version of this truck allows you to direct our characters to walk to and enter the truck through any of the doors all with one simple point and click. The truck can then drive with another click, tires spinning and all. Antics Technologies provides user-friendly, real-time 3D animation software, including a free BasePack version, that allows anyone to produce 3D animations using simple point-and-click commands. Models from Google SketchUp can easily be imported into Antics3D using a browser window into the Google 3D Warehouse from within Antics3D. The vast Google 3D Warehouse allows you to build the exact sets and scenes that you want. Together with Antics3D intelligent characters and props as well as sophisticated camera choreography, this gives you the power to bring life to your scenes and create animated clips, films and visualizations.',NULL,'chevrolet',NULL,'silverado',5.665259838104249823,2.439559936523440164,2.07423515385017021,'black',NULL,'truck','https://3dwarehouse.sketchup.com/model/bbb89eca7fed0cdb872192610795619a/Chevy-Silverado-4door-pickup-truck',NULL,NULL,'{"VehicleType":null}');
INSERT INTO CadModel VALUES(1165,'1cf17a1e1841d10c9e6a3356df3f3d9a','91f36aacbde112e168742254bcf1c9e9','2005 Chrysler Pacifica','The Chrysler Pacifica was a mid-size crossover SUV, originally produced by DaimlerChrysler and transferred to Chrysler LLC, when it was spun off in 2007. As frequently reported, the Pacifica does share its platform with the Chrysler minivans. It offers all-wheel drive and an upscale interior to individuals who need cargo and passenger flexibility. It was introduced in 2004 and was originally inspired by the 1999 Chrysler Pacifica and 2000 Chrysler Citadel concept cars. The Pacifica, according to Chrysler, is a sports tourer and is built in Windsor, Ontario, Canada alongside the long-wheelbase Chrysler Town & Country and the Dodge Grand Caravan. Original by andrzej kowalski. #2000s #4WD #American #Automobile #Car #Chrysler_Pacifica #Chyrsler #Crossover #FF #Luxury #Midsize #Pacifica #Stock #SUV #Transportation #V6 #Vehicle',NULL,'chrysler','2005','pacifica',5.033939838409420275,2.157320022583010033,1.728835037909449924,NULL,NULL,'passenger','https://3dwarehouse.sketchup.com/model/1cf17a1e1841d10c9e6a3356df3f3d9a/2005-Chrysler-Pacifica',NULL,NULL,'{"VehicleType":null}');
